define([],function(){
'use strict';
const init = () => {
    const list = document.getElementById('u-route-list');
    if (!list) {
        return;
    }

    let dragged = null;

    const renumber = () => {
        [...list.querySelectorAll('.u-route-item')].forEach((item, index) => {
            const number = item.querySelector('.u-route-item__order');
            if (number) {
                number.textContent = String(index + 1);
            }
            const up = item.querySelector('[data-u-move="up"]');
            const down = item.querySelector('[data-u-move="down"]');
            if (up) {
                up.disabled = index === 0;
            }
            if (down) {
                down.disabled = index === list.children.length - 1;
            }
        });
    };

    list.querySelectorAll('.u-route-item').forEach((item) => {
        item.addEventListener('dragstart', () => {
            dragged = item;
            item.classList.add('is-dragging');
        });

        item.addEventListener('dragend', () => {
            item.classList.remove('is-dragging');
            dragged = null;
            renumber();
        });

        item.addEventListener('dragover', (event) => {
            event.preventDefault();
            if (!dragged || dragged === item) {
                return;
            }
            const rect = item.getBoundingClientRect();
            const after = event.clientY > rect.top + rect.height / 2;
            if (after) {
                item.after(dragged);
            } else {
                item.before(dragged);
            }
        });

        item.querySelectorAll('[data-u-move]').forEach((button) => {
            button.addEventListener('click', () => {
                const direction = button.dataset.uMove;
                if (direction === 'up' && item.previousElementSibling) {
                    item.previousElementSibling.before(item);
                }
                if (direction === 'down' && item.nextElementSibling) {
                    item.nextElementSibling.after(item);
                }
                renumber();
                item.focus?.();
            });
        });
    });

    renumber();
};

return {init:init};
});
